import json,random,math,collections
from pathlib import Path
W=json.loads(Path('/tmp/voy-entropy/clean_works.json').read_text())
def calc(words,k):
 counts=collections.Counter(words);stop=set(w for w,_ in sorted(counts.items(),key=lambda x:-x[1])[:k]); seq=[w for w in words if w not in stop]; c=collections.Counter((a,b) for i,a in enumerate(seq) for b in seq[i+1:i+4] if a!=b); pair={tuple(sorted((a,b))) for a,b in c}; skew=sum(abs(c[a,b]-c[b,a])>5 for a,b in pair); f=collections.Counter(seq);return {'tokens':len(seq),'types':len(f),'hapax':sum(v==1 for v in f.values()),'pairs':len(pair),'pair_occurrences':sum(c.values()),'skewed':skew,'skew_type_ratio':skew/len(pair) if pair else 0,'skew_instance_ratio':skew/sum(c.values()) if c else 0,'types_per_token':len(f)/len(seq),'hapax_per_token':sum(v==1 for v in f.values())/len(seq)}
def encode(words,mode,seed):
 rng=random.Random(seed); abc='abcdefghijklmnopqrstuvwxyz'; perms=list(abc);rng.shuffle(perms); mapping=dict(zip(abc,perms));return [''.join(mapping[ch] if mode=='simple' else mapping[ch]+str(rng.randrange(3)) for ch in w) for w in words]
# Planted asymmetric sequence has repeated A B C, random order preserves counts.
toy=['a','b','c','d','e']*400; assert calc(toy,0)['skewed']>0
out={}
for cid in ('la_augustine','it_dante','de_nibelunge'):
 words=' '.join(W[cid]).split()[:7000];assert len(words)==7000
 ranks=[0,1,math.ceil(len(set(words))*.01)]; rr={}
 for k in ranks:
  r={'original':calc(words,k),'mono':calc(encode(words,'simple',408),k),'homophonic':[calc(encode(words,'homophonic',seed),k) for seed in range(3)],'shuffle':[]}
  for seed in range(10):
   shuffled=words.copy();random.Random(seed).shuffle(shuffled);r['shuffle'].append(calc(shuffled,k))
  assert r['original']==r['mono']; rr[str(k)]=r
 out[cid]=rr
print(json.dumps(out,indent=2));
